// Server-only: OPENAI LIVE calls on the Archil disk.
//
// GPT-Live stores no transcripts we can list or read back, so this app keeps
// its own. Layout, under <root>/openai-live/:
//
//   calls/<userId>/<callId>.json         the call record (LiveCallRecord)
//   index/<userId>/<inverted>_<callId>   empty marker, one per call
//
// <inverted> is a fixed-width countdown from the call's start time, so a plain
// lexicographic listing of the index is newest first, and `startAfter` pages
// back in time without reading any record. Records are keyed by the visitor's
// opaque id, so reading one is also the ownership check.

import type { Lang } from "@/lib/lang";
import { ARCHIL_ROOT, archilDisk, isNotFound } from "@/lib/storage/archil";
import type { ConversationDetail, ConversationSummary, ConversationTurn } from "./types";

export interface LiveCallRecord {
  v: 1;
  id: string;
  userId: string;
  personaId: string;
  lang: Lang;
  /** The memory.recall tool was on: ingest into mem0 when the call ends. */
  memory: boolean;
  /** Unix seconds. */
  startedAt: number;
  updatedAt: number;
  endedAt?: number;
  status: "open" | "done";
  /** The stored call this one continued, if any. */
  resumedFrom?: string;
  turns: ConversationTurn[];
}

export interface IndexEntry {
  /** Marker name within the visitor's index, usable as a listing cursor. */
  name: string;
  callId: string;
  startedAt: number;
}

const ROOT = `${ARCHIL_ROOT}/openai-live`;
// Countdown base: far past any real start time, fixed width for sorting.
const MAX_SECS = 99_999_999_999;
const INVERTED_WIDTH = 11;
const INDEX_NAME_RE = /^(\d{11})_(olc_[0-9a-f]{32})$/;
/** An open call untouched this long was abandoned (tab closed, server restarted). */
const ABANDONED_SECS = 15 * 60;
const TITLE_CHARS = 60;

const callKey = (userId: string, callId: string) => `${ROOT}/calls/${userId}/${callId}.json`;
const indexPrefix = (userId: string) => `${ROOT}/index/${userId}/`;
const indexName = (startedAt: number, callId: string) =>
  `${String(MAX_SECS - startedAt).padStart(INVERTED_WIDTH, "0")}_${callId}`;

export function nowSecs(): number {
  return Math.floor(Date.now() / 1000);
}

export async function putCall(record: LiveCallRecord): Promise<void> {
  const disk = await archilDisk();
  await disk.putObject(callKey(record.userId, record.id), JSON.stringify(record), "application/json");
}

/** Store a new call and its index marker. */
export async function createCall(record: LiveCallRecord): Promise<void> {
  const disk = await archilDisk();
  await putCall(record);
  await disk.putObject(indexPrefix(record.userId) + indexName(record.startedAt, record.id), "");
}

/** The visitor's call, or null if they have none with this id. */
export async function getCall(userId: string, callId: string): Promise<LiveCallRecord | null> {
  const disk = await archilDisk();
  try {
    const bytes = await disk.getObject(callKey(userId, callId));
    const record = JSON.parse(new TextDecoder().decode(bytes)) as LiveCallRecord;
    return record.userId === userId && record.id === callId ? record : null;
  } catch (err) {
    if (isNotFound(err)) return null;
    throw err;
  }
}

/** Index entries newest first, after `after` (a previous entry's name). */
export async function listIndex(
  userId: string,
  after: string | null,
  limit: number,
): Promise<{ entries: IndexEntry[]; truncated: boolean }> {
  const disk = await archilDisk();
  const prefix = indexPrefix(userId);
  const res = await disk.listObjects(prefix, {
    limit,
    ...(after ? { startAfter: prefix + after } : {}),
  });
  const entries: IndexEntry[] = [];
  for (const obj of res.objects) {
    const name = obj.key.slice(prefix.length);
    const m = INDEX_NAME_RE.exec(name);
    if (m) entries.push({ name, callId: m[2], startedAt: MAX_SECS - Number(m[1]) });
  }
  return { entries, truncated: res.isTruncated };
}

/** Worth listing: the visitor spoke, and the call is over (or was abandoned). */
export function isListable(record: LiveCallRecord, now = nowSecs()): boolean {
  if (!record.turns.some((t) => t.who === "user")) return false;
  return record.status === "done" || now - record.updatedAt > ABANDONED_SECS;
}

export function summarizeCall(record: LiveCallRecord): ConversationSummary {
  const firstUser = record.turns.find((t) => t.who === "user")?.text ?? "";
  // GPT-Live gives no generated title; the visitor's opening line stands in.
  const title = firstUser.length > TITLE_CHARS ? `${firstUser.slice(0, TITLE_CHARS)}…` : firstUser;
  return {
    id: record.id,
    source: "openai-live",
    personaId: record.personaId,
    lang: record.lang,
    title,
    summary: "",
    startedAt: record.startedAt,
    durationSecs: Math.max(0, (record.endedAt ?? record.updatedAt) - record.startedAt),
    messageCount: record.turns.length,
  };
}

export function detailOfCall(record: LiveCallRecord): ConversationDetail {
  return { ...summarizeCall(record), transcript: record.turns };
}

// Server-only: capture an OPENAI LIVE call's transcript over a sideband.
//
// After creating a session, the server attaches its own WebSocket to it
// (wss://…/v1/live/sessions/{id}/attach, project key) and hears the same
// transcript deltas as the browser. The stored transcript therefore comes from
// OpenAI, not from the browser, and survives a closed tab. The record is
// checkpointed while the call runs and finalized at session.closed (or when the
// sideband drops), which is also when the call is ingested into mem0.
//
// Each capture lives in this server process (dev: `next dev`). A restart
// mid-call loses the tail since the last checkpoint; the record then shows as
// abandoned in history.

import { appendTranscriptDelta, settledTurns, type LiveTurn } from "./live-transcript";
import { nowSecs, putCall, type LiveCallRecord } from "./live-store";

const ATTACH_URL = "wss://api.openai.com/v1/live/sessions";
const CHECKPOINT_MS = 10_000;
// GPT-Live connected calls are capped at 2 hours; stop listening a bit after.
const MAX_CAPTURE_MS = 2 * 60 * 60 * 1000 + 5 * 60 * 1000;
// The attach replays the last 3 s; event ids dedupe it.
const MAX_SEEN_IDS = 10_000;

interface SidebandEvent {
  type?: string;
  event_id?: string;
  delta?: string;
  start_ms?: number;
  end_ms?: number;
  reason?: string;
  error?: { message?: string };
}

export interface CaptureOptions {
  apiKey: string;
  /** The GPT-Live session id from creation (opaque; never stored as our id). */
  sessionId: string;
  record: LiveCallRecord;
  /** Runs once after the final record is written (mem0 ingest). */
  onFinished: (record: LiveCallRecord) => Promise<void>;
}

// Node's WebSocket (undici) takes request headers in its init object; the DOM
// typings only know the protocols argument.
type HeaderWebSocket = new (url: string, init: { headers: Record<string, string> }) => WebSocket;

class LiveCapture {
  private turns: LiveTurn[] = [];
  private seen = new Set<string>();
  private dirty = false;
  private finished = false;
  private writing: Promise<void> = Promise.resolve();
  private ws: WebSocket | null = null;
  private checkpointTimer: ReturnType<typeof setInterval> | null = null;
  private deadline: ReturnType<typeof setTimeout> | null = null;

  constructor(private readonly opts: CaptureOptions) {}

  start(): void {
    const url = `${ATTACH_URL}/${encodeURIComponent(this.opts.sessionId)}/attach`;
    const ws = new (WebSocket as unknown as HeaderWebSocket)(url, {
      headers: { Authorization: `Bearer ${this.opts.apiKey}` },
    });
    this.ws = ws;
    ws.onmessage = (msg) => this.onMessage(msg.data);
    ws.onerror = () => console.warn(`[live-capture] sideband error for ${this.opts.record.id}`);
    ws.onclose = () => void this.finish();
    this.checkpointTimer = setInterval(() => this.checkpoint(), CHECKPOINT_MS);
    this.deadline = setTimeout(() => void this.finish(), MAX_CAPTURE_MS);
  }

  private onMessage(data: unknown): void {
    if (typeof data !== "string") return;
    let ev: SidebandEvent;
    try {
      ev = JSON.parse(data) as SidebandEvent;
    } catch {
      return;
    }
    if (ev.event_id) {
      if (this.seen.has(ev.event_id)) return;
      if (this.seen.size >= MAX_SEEN_IDS) this.seen.clear();
      this.seen.add(ev.event_id);
    }
    switch (ev.type) {
      case "session.input_transcript.delta":
      case "session.output_transcript.delta": {
        const who = ev.type === "session.input_transcript.delta" ? "user" : "agent";
        this.turns = appendTranscriptDelta(this.turns, who, ev.delta ?? "", ev.start_ms, ev.end_ms);
        this.dirty = true;
        break;
      }
      case "session.closed":
        void this.finish();
        break;
      case "error":
        console.warn(`[live-capture] ${this.opts.record.id}: ${ev.error?.message ?? "error"}`);
        break;
      default:
        break;
    }
  }

  /** Write the record with the turns so far; writes never overlap. */
  private write(final: boolean): Promise<void> {
    const turns = settledTurns(this.turns);
    const now = nowSecs();
    const record: LiveCallRecord = {
      ...this.opts.record,
      turns,
      updatedAt: now,
      ...(final ? { status: "done", endedAt: now } : {}),
    };
    this.writing = this.writing
      .then(() => putCall(record))
      .catch((err: unknown) => {
        console.warn(`[live-capture] write failed for ${record.id}:`, err);
      });
    return this.writing.then(() => {
      if (final) this.opts.record = record;
    });
  }

  private checkpoint(): void {
    if (!this.dirty || this.finished) return;
    this.dirty = false;
    void this.write(false);
  }

  private async finish(): Promise<void> {
    if (this.finished) return;
    this.finished = true;
    captures.delete(this.opts.record.id);
    if (this.checkpointTimer) clearInterval(this.checkpointTimer);
    if (this.deadline) clearTimeout(this.deadline);
    try {
      this.ws?.close();
    } catch {
      // already closed
    }
    await this.write(true);
    try {
      await this.opts.onFinished(this.opts.record);
    } catch (err) {
      console.warn(`[live-capture] post-call step failed for ${this.opts.record.id}:`, err);
    }
  }
}

// One capture per call, kept on globalThis so a dev-server module reload
// doesn't orphan running captures.
const store = globalThis as typeof globalThis & { __tsubakiLiveCaptures?: Map<string, LiveCapture> };
const captures = (store.__tsubakiLiveCaptures ??= new Map<string, LiveCapture>());

/** Attach to a just-created session and record its transcript until it closes. */
export function startLiveCapture(opts: CaptureOptions): void {
  if (captures.has(opts.record.id)) return;
  const capture = new LiveCapture(opts);
  captures.set(opts.record.id, capture);
  capture.start();
}

